    apiKey: process.env.ALCHEMYST_AI_API_KEY,
  });

  try {
    await client.v1.context.add({
      context_type: 'resource',
      documents: [{ content: "The secret launch code for Project Nova is 8847-ALPHA." }],
      source: 'docs',
      scope: 'internal',
      metadata: {
        fileName: "nova_secret.txt",
        groupName: ["eng"]
      },
